func TestReferenceAnnotationRecordedDOM(t *testing.T) {
	p, _ := testReferenceEmojiProvider(t)
	font := ui.Font{Family: "Segoe UI", Size: 15, Weight: 600, LineHeight: 1.5}
	for _, test := range referenceAnnotationDOMVectors {
		rows, height, exact, err := referenceAnnotationRows(test.text, font, test.width, test.duet, p)
		if err != nil || !exact || height != test.height || len(rows) != len(test.rows) {
			t.Fatalf("%q width=%v duet=%v: rows=%d height=%v exact=%v err=%v; DOM rows=%q height=%v", test.text, test.width, test.duet, len(rows), height, exact, err, test.rows, test.height)
		}
		for i, row := range rows {
			if annotationAuditVisible(row.text) != test.rows[i] || math.Abs(float64(row.x-test.x[i])) > .06 || row.y != float32(i)*22.5 {
				t.Fatalf("%q width=%v duet=%v row%d: text=%q x=%v y=%v; DOM text=%q x=%v", test.text, test.width, test.duet, i, row.text, row.x, row.y, test.rows[i], test.x[i])
			}
			if row.context == "" || row.startRune < 0 || row.endRune <= row.startRune {
				t.Fatal("prepared row lost paragraph context or half-open rune range")
			}
		}
	}
	t.Logf("%d actual DOM annotation vectors passed, including exact 1/64 DIP wrap boundaries", len(referenceAnnotationDOMVectors))
}

func TestReferenceAnnotationKeepsParagraphContextAtPhysicalScale(t *testing.T) {
	p, _ := testReferenceEmojiProvider(t)
	font := ui.Font{Family: "Segoe UI", Size: 15, Weight: 600, LineHeight: 1.5}
	rows, _, exact, err := referenceAnnotationRows("אבג 👩‍👩‍👧‍👦! 中 文", font, 41.2, false, p)
	if err != nil || !exact || len(rows) != 3 || rows[1].text != "👩‍👩‍👧‍👦! 中" {
		t.Fatalf("lost actual DOM context: rows=%d exact=%v err=%v", len(rows), exact, err)
	}
	row := rows[1]
	contextual := p.ShapeRange(row.context, row.startRune, row.endRune, font)
	independent := p.Shape(row.text, font)
	if contextual.Err != nil || !contextual.Exact || len(contextual.Colors) == 0 || contextual.Width >= 41.2 || independent.Width <= 41.2 {
		t.Fatalf("context did not preserve Hebrew emoji GPOS: contextualWidth=%v independentWidth=%v err=%v", contextual.Width, independent.Width, contextual.Err)
	}
	physical := font
	physical.Size *= 1.25
	shaped := p.ShapeRange(row.context, row.startRune, row.endRune, physical)
	if shaped.Err != nil || !shaped.Exact || math.Abs(float64(shaped.Width/1.25-contextual.Width)) > .03 {
		t.Fatalf("physical context: width=%v logical=%v err=%v", shaped.Width, contextual.Width, shaped.Err)
	}
	for _, g := range shaped.Glyphs {
		if g.Cluster < 0 || g.Runes < 1 || g.Cluster+g.Runes > row.endRune-row.startRune {
			t.Fatal("row glyph uses paragraph indices rather than row rune indices")
		}
	}
	for _, test := range [][2]int{{-1, 1}, {0, 1000}, {5, 11}} {
		if bad := p.ShapeRange(row.context, test[0], test[1], font); bad.Exact || bad.Err == nil {
			t.Fatalf("accepted invalid range %v", test)
		}
	}
}

func TestReferenceAnnotationBoundsWhitespaceAndOverflow(t *testing.T) {
	p, _ := testReferenceEmojiProvider(t)
	font := ui.Font{Family: "Segoe UI", Size: 15, Weight: 600, LineHeight: 1.5}
	if rows, h, exact, err := referenceAnnotationRows(" \t\r\n\f ", font, 20, false, p); len(rows) != 0 || h != 0 || !exact || err != nil {
		t.Fatal("CSS normal whitespace-only content retained a line box")
	}
	rows, _, exact, err := referenceAnnotationRows("A\u00a0B C", font, 10, true, p)
	if err != nil || !exact || len(rows) != 2 || rows[0].text != "A\u00a0B" || rows[0].x != 0 {
		t.Fatal("NBSP or safe overflow alignment differs from DOM")
	}
	for _, text := range []string{strings.Repeat("x", lineByteLimit+1), strings.Repeat("漢", lineWordLimit*2+1)} {
		if _, _, exact, err := referenceAnnotationRows(text, font, 1, false, p); exact || !errors.Is(err, errReferenceAnnotationLimit) {
			t.Fatalf("input/row budget not enforced: exact=%v err=%v", exact, err)
		}
	}
	if _, _, exact, err := referenceAnnotationRows("text", font, 20, false, nil); exact || !errors.Is(err, errReferenceAnnotationContext) {
		t.Fatal("nil provider claimed paragraph line shaping")
	}
}

func BenchmarkReferenceAnnotationPreparation(b *testing.B) {
	owner, err := openEmojiColorFont(filepath.Join(os.Getenv("WINDIR"), "Fonts", "seguiemj.ttf"))
	if err != nil {
		b.Skipf("system Segoe UI Emoji unavailable: %v", err)
	}
	p := newReferenceFontProvider(owner)
	b.Cleanup(func() { p.Close(); owner.Close() })
	font := ui.Font{Family: "Segoe UI", Size: 15, Weight: 600, LineHeight: 1.5}
	for _, test := range []struct {
		name, text string
		width      float32
	}{{"CJK", "这是翻译后的歌词，每个字都有自己的位置。", 180}, {"emoji-boundary", "😀😀", 41.2}, {"Hebrew-context", "אבג 👩‍👩‍👧‍👦! 中 文", 41.2}} {
		b.Run(test.name+"/native", func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				ui.ShapeText(test.text, font, test.width)
			}
		})
		b.Run(test.name+"/context", func(b *testing.B) {
			b.ReportAllocs()
			for b.Loop() {
				referenceAnnotationRows(test.text, font, test.width, false, p)
			}
		})
	}
}
